def ratakan(d, awalan=""):
    hasil = {}
    for k, v in d.items():
        kunci = awalan + "." + k if awalan else k
        if isinstance(v, dict):
            hasil.update(ratakan(v, kunci))
        else:
            hasil[kunci] = v
    return hasil
